) COMMENT='股票分类字典';

CREATE TABLE dict_industry (
    industry_code VARCHAR(20) PRIMARY KEY COMMENT '行业代码（国标）',
    industry_name VARCHAR(100) NOT NULL COMMENT '行业名称'
) COMMENT='行业分类字典';

CREATE TABLE energy_type_dict (
    type_code VARCHAR(10) PRIMARY KEY COMMENT '能源类型代码',
    type_name VARCHAR(30) NOT NULL COMMENT '类型名称',
    category VARCHAR(20) COMMENT '大类',
    is_renewable TINYINT(1) DEFAULT 0 COMMENT '是否可再生'
) ENGINE=InnoDB COMMENT='能源类型字典';

CREATE TABLE energy_type_dict (
    type_code VARCHAR(10) PRIMARY KEY COMMENT '能源类型代码',
    type_name VARCHAR(30) NOT NULL COMMENT '类型名称',
    category VARCHAR(20) COMMENT '大类',
    is_renewable TINYINT(1) DEFAULT 0 COMMENT '是否可再生'
) ENGINE=InnoDB COMMENT='能源类型字典';

CREATE TABLE energy_type_dict (
    type_code VARCHAR(10) PRIMARY KEY COMMENT '能源类型代码',
    type_name VARCHAR(30) NOT NULL COMMENT '类型名称',
    category VARCHAR(20) COMMENT '大类',
    is_renewable TINYINT(1) DEFAULT 0 COMMENT '是否可再生'
) ENGINE=InnoDB COMMENT='能源类型字典';

CREATE TABLE energy_position_dict (
    position_code VARCHAR(20) PRIMARY KEY COMMENT '岗位代码',
    position_name VARCHAR(50) NOT NULL COMMENT '岗位名称',
    category VARCHAR(30) COMMENT '类别'
) ENGINE=InnoDB COMMENT='能源行业岗位字典';

CREATE TABLE station_type_dict (
    type_code VARCHAR(10) PRIMARY KEY COMMENT '场站类型代码',
    type_name VARCHAR(50) NOT NULL COMMENT '类型名称',
    category VARCHAR(30) COMMENT '大类'
) ENGINE=InnoDB COMMENT='场站类型字典';

CREATE TABLE cert_type_dict (
    cert_type_code VARCHAR(20) PRIMARY KEY COMMENT '资质类型代码',
    cert_type_name VARCHAR(50) NOT NULL COMMENT '资质类型名称',
    category VARCHAR(20) COMMENT '类别',
    valid_years TINYINT COMMENT '有效期(年)'
) ENGINE=InnoDB COMMENT='资质类型字典';

CREATE TABLE order_status_dict (
  status_code VARCHAR(32) NOT NULL COMMENT '订单状态编码',
  status_name VARCHAR(64) NOT NULL COMMENT '订单状态名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (status_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单状态字典';

CREATE TABLE payment_status_dict (
  status_code VARCHAR(32) NOT NULL COMMENT '支付状态编码',
  status_name VARCHAR(64) NOT NULL COMMENT '支付状态名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (status_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付状态字典';

CREATE TABLE payment_status_dict (
  status_code VARCHAR(32) NOT NULL COMMENT '支付状态编码',
  status_name VARCHAR(64) NOT NULL COMMENT '支付状态名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (status_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付状态字典';

CREATE TABLE dict_exam_item (
    item_code VARCHAR(20) PRIMARY KEY COMMENT '考试项目代码',
    item_name VARCHAR(50) NOT NULL COMMENT '考试项目名称',
    default_weight DECIMAL(5,2) COMMENT '默认权重（如平时成绩占30%）'
);

CREATE TABLE dict_grade_level (
    grade_level CHAR(2) PRIMARY KEY COMMENT '等级(A/B/C/D/F)',
    min_score INT COMMENT '最低分数',
    max_score INT COMMENT '最高分数',
    grade_point DECIMAL(3,2) COMMENT '绩点'
);

CREATE TABLE energy_position_dict (
    position_code VARCHAR(20) PRIMARY KEY COMMENT '岗位代码',
